   "ess2_24": [{ q: "Why do you look so clean?", o: ["I was using a journal.", "I just took a bath.", "I marvel at my abilities.", "I regret buying it."], a: "I just took a bath." }, { q: "Can you touch your toes?", o: ["I marvel at my abilities.", "No, I can't bend that far.", "Yes, I recall it was wonderful.", "It uses sufficient gas."], a: "No, I can't bend that far." }, { q: "Do you remember the movie we saw together?", o: ["Yes, I recall it was wonderful.", "No, I think it was fiction.", "We should have a flag in the corner.", "No, I can't bend that far."], a: "Yes, I recall it was wonderful." }, { q: "What do you think we need for our classroom?", o: ["We should have a flag in the corner.", "Yes, I think it is fantastic.", "I just took a bath.", "I regret buying it."], a: "We should have a flag in the corner." }, { q: "How do you feel about your new car?", o: ["It uses sufficient gas.", "I regret buying it.", "I was using a journal.", "Yes, I recall it was wonderful."], a: "I regret buying it." }, { q: "When you want to learn about history, ______.", o: ["you should read an academic journal", "you should read fiction", "there is usually a flag", "they only drink liquids"], a: "you should read an academic journal" }, { q: "In front of a government building, ______.", o: ["there is usually a flag", "there are usually baths", "their soul goes to heaven", "it was fantastic"], a: "there is usually a flag" }, { q: "When people die, ______.", o: ["they have to get surgery", "their soul goes to heaven", "Ali was disabled", "to get more nutrients"], a: "their soul goes to heaven" }, { q: "A lot of people eat too quickly. ______.", o: ["They hardly chew their food", "They only drink liquids", "It was sufficient", "Ali had a tube"], a: "They hardly chew their food" }, { q: "The movie was better than we imagined. ______.", o: ["It was sufficient", "It was fantastic", "I marvel at it", "then you will feel tough"], a: "It was fantastic" }, { q: "This is an important decision. ______.", o: ["I feel like I need to bend forward", "I don't want to have to regret making a mistake", "inspect it carefully", "to get more nutrients"], a: "I don't want to have to regret making a mistake" }, { q: "Before you buy a car, ______.", o: ["marvel at it", "inspect it carefully", "and overcame his fear of heights", "Ali was disabled"], a: "inspect it carefully" }, { q: "After the accident, ______.", o: ["Ali was disabled", "Ali had a tube", "their soul goes to heaven", "you should read fiction"], a: "Ali was disabled" }, { q: "Memorize this address, ______.", o: ["then you will feel tough", "so you will be able to recall it in the future", "and overcame his fear of heights", "there are usually baths"], a: "so you will be able to recall it in the future" }, { q: "He climbed the mountain ______.", o: ["and overcame his fear of heights", "to get more nutrients", "they have to get surgery", "it was sufficient"], a: "and overcame his fear of heights" }],
   "ess2_25": [{ q: "Choose the right word for the definition 'a group of twelve':", o: ["bin", "neat", "cash", "dozen"], a: "dozen" }, { q: "Choose the right word for the definition 'to say loudly':", o: ["yell", "inspire", "admit", "mere"], a: "yell" }, { q: "Choose the right word for the definition 'relating to the face':", o: ["bowl", "facial", "nap", "wallet"], a: "facial" }, { q: "Choose the right word for the definition 'not polite':", o: ["settle", "vehicle", "rude", "occasion"], a: "rude" }, { q: "Choose the right word for the definition 'an older person':", o: ["criminal", "elder", "penalty", "fence"], a: "elder" }, { q: "I love sports, and I want to ______ children to play sports, too.", o: ["mere", "penalty", "inspire", "neat"], a: "inspire" }, { q: "Mia's ______ for not stopping at a red light was $50.", o: ["bowl", "penalty", "inspire", "mere"], a: "penalty" }, { q: "After he took a shower and got dressed, my brother looked very ______.", o: ["neat", "mere", "penalty", "inspire"], a: "neat" }, { q: "The cat ate his food out of a black ______.", o: ["bowl", "penalty", "mere", "neat"], a: "bowl" }, { q: "He was only given a ______ five dollars for his hard work.", o: ["mere", "penalty", "inspire", "neat"], a: "mere" }],
   "ess2_26": [{ q: "He blamed me of taking the last piece of pie. (Which word means 'blamed')?", o: ["accuse", "adjust", "amuse", "engage"], a: "accuse" }, { q: "The man's bedroom was very simple. (Which word means 'simple')?", o: ["plain", "grand", "firm", "strict"], a: "plain" }, { q: "The clown likes to entertain children. (Which word means 'entertain')?", o: ["amuse", "accuse", "adjust", "engage"], a: "amuse" }, { q: "I need to change the way I run so I can be faster. (Which word means 'change')?", o: ["adjust", "accuse", "amuse", "engage"], a: "adjust" }, { q: "During their free time, the children did many different activities. (Which word completes 'did many different activities' / 'engage in')?", o: ["engage", "adjust", "accuse", "amuse"], a: "engage" }, { q: "This cloth dress is one of my favorites. (Which word means 'cloth')?", o: ["cotton", "coral", "deck", "fuel"], a: "cotton" }, { q: "The bad storm over the ocean almost reached the land. (Which word means 'bad storm over the ocean')?", o: ["hurricane", "loss", "reef", "zone"], a: "hurricane" }, { q: "Tightly close the window before the rain starts! (Which word means 'close')?", o: ["shut", "surf", "strict", "task"], a: "shut" }, { q: "He will hit something and break his bike if he closes his eyes while riding. (Which word means 'hit something and break')?", o: ["crash", "cotton", "coral", "deck"], a: "crash" }, { q: "The army fights in the war area. (Which word means 'area')?", o: ["zone", "reef", "loss", "task"], a: "zone" }],
